<?php
use App\Models\AlumniKriteria; use App\Models\AlumniPeserta; use App\Services\AlumniScoringService; use App\Services\AlumniWorkflowService; use Livewire\Attributes\Computed; use Livewire\Attributes\Layout; use Livewire\Attributes\Title; use Livewire\Attributes\Url; use Livewire\Component; use Livewire\WithPagination;
new #[Layout('layouts.app'), Title('Penilaian Alumni')] class extends Component { use WithPagination; #[Url] public string $search=''; #[Url(as:'penilaian')] public string $penilaian='belum'; public ?int $selectedId=null; public array $scores=[]; public function mount():void{} public function updatedSearch():void{$this->resetPage();} public function updatedPenilaian():void{$this->resetPage();} #[Computed] public function participants(){return AlumniPeserta::query()->with('activeVideo')->where('status_kurasi','lolos')->when($this->search,fn($q)=>$q->where(fn($nested)=>$nested->where('nama_lengkap','like','%'.$this->search.'%')->orWhereHas('activeVideo',fn($v)=>$v->where('original_name','like','%'.$this->search.'%'))))->when($this->penilaian,fn($q)=>$q->where('status_penilaian',$this->penilaian))->latest('registered_at')->paginate(12);} #[Computed] public function selected():?AlumniPeserta{return $this->selectedId?AlumniPeserta::query()->with('activeVideo')->find($this->selectedId):null;} #[Computed] public function criteria(){return $this->selected?AlumniKriteria::query()->where('periode',$this->selected->periode)->where('aktif',true)->orderBy('urutan')->get():collect();} public function select(int $id):void{$this->selectedId=$id;$this->scores=AlumniPeserta::findOrFail($id)->penilaian()->where('juri_id',auth()->id())->pluck('nilai','kriteria_id')->map(fn($v)=>(string)$v)->all();} public function save(AlumniWorkflowService $workflow):void{$workflow->score(AlumniPeserta::findOrFail($this->selectedId),(int)auth()->id(),$this->scores);$this->dispatch('toast',type:'success',message:'Nilai berhasil disimpan.');} };
?>
<div class="space-y-5"><div><flux:heading size="xl">Penilaian Karya</flux:heading><flux:subheading>Nilai diberikan berdasarkan kriteria aktif periode peserta.</flux:subheading></div><flux:card><div class="grid gap-3 md:grid-cols-3"><flux:input wire:model.live.debounce.400ms="search" placeholder="Cari peserta atau karya…"/><flux:select wire:model.live="penilaian"><option value="">Semua penilaian</option><option value="belum">Belum dinilai</option><option value="sudah">Sudah dinilai</option></flux:select></div></flux:card><flux:card><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="text-xs text-zinc-500"><tr><th class="px-2 py-2">Peserta</th><th class="px-2 py-2">Angkatan</th><th class="px-2 py-2">Karya</th><th class="px-2 py-2">Status</th><th></th></tr></thead><tbody>@forelse($this->participants as $peserta)<tr class="border-t border-zinc-200 dark:border-zinc-800"><td class="px-2 py-2 font-medium">{{ $peserta->nama_lengkap }}</td><td class="px-2 py-2">{{ $peserta->tahun_kelulusan }}</td><td class="px-2 py-2">{{ $peserta->activeVideo?->original_name ?? '—' }}</td><td class="px-2 py-2"><x-alumni.status-badge :status="$peserta->status_penilaian"/></td><td class="px-2 py-2"><button wire:click="select({{ $peserta->id }})" class="text-amber-700">Beri nilai</button></td></tr>@empty<tr><td colspan="5" class="px-2 py-10 text-center text-zinc-500">Tidak ada karya yang dapat dinilai.</td></tr>@endforelse</tbody></table></div><div class="mt-4">{{ $this->participants->links() }}</div></flux:card>@if($this->selected)<flux:card><div class="grid gap-5 xl:grid-cols-2"><div><flux:heading size="lg">{{ $this->selected->nama_lengkap }}</flux:heading><div class="mt-4"><x-alumni.video-player :video="$this->selected->activeVideo"/></div>@if($this->selected->activeVideo)<a class="mt-3 inline-block text-sm text-amber-700" href="{{ route('alumni.video.download',$this->selected->activeVideo) }}">Unduh video</a>@endif</div><div><flux:heading size="lg">Input nilai</flux:heading>@forelse($this->criteria as $criterion)<div class="mt-3"><flux:input wire:model="scores.{{ $criterion->id }}" type="number" min="0" max="100" step="0.01" label="{{ $criterion->nama }} (bobot {{ $criterion->bobot }})"/></div>@empty<p class="mt-3 text-sm text-zinc-500">Belum ada kriteria aktif untuk periode ini.</p>@endforelse@if($this->criteria->isNotEmpty())<flux:button class="mt-4" wire:click="save" wire:confirm="Simpan nilai karya ini?" variant="primary">Simpan nilai</flux:button>@endif</div></div></flux:card>@endif</div>
